/* @lc app=leetcode id=2172 lang=kotlin */ class Solution { fun maximumANDSum(nums: IntArray, numSlots: Int): Int = generateSequence(1) { it * 3 }.take(numSlots).toList().let { p3 -> nums.fold(mapOf(0 to 0)) { cur, x -> HashMap<Int, Int>().also { nxt -> cur.forEach { (st, v) -> (0 until numSlots).filter { s -> st / p3[s] % 3 < 2 }.forEach { s -> nxt.merge(st + p3[s], v + (x and (s + 1))) { a, b -> maxOf(a, b) } } } } }.values.max() } }